import{_ as i,a0 as m,w as r,s as l,I as n,x as t,a1 as a,A as p,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"用數據科學搭建一個實時推薦引擎 | LCTT x X-CMD","titleTemplate":false,"description":"用數據科學搭建一個實時推薦引擎 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用數據科學搭建一個實時推薦引擎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用數據科學搭建一個實時推薦引擎 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20160817 Building a Real-Time Recommendation Engine with Data Science","title":"用數據科學搭建一個實時推薦引擎","tag":"201612","desc":""},"relativePath":"201612/20160817 Building a Real-Time Recommendation Engine with Data Science.md","filePath":"[post].md"}'),d={name:"201612/20160817 Building a Real-Time Recommendation Engine with Data Science.md"};function c(u,e,g,h,w,C){const o=m("Link");return r(),l("div",null,[e[26]||(e[26]=n("h1",{id:"用數據科學搭建一個實時推薦引擎",tabindex:"-1"},[t("用數據科學搭建一個實時推薦引擎 "),n("a",{class:"header-anchor",href:"#用數據科學搭建一個實時推薦引擎","aria-label":"Permalink to “用數據科學搭建一個實時推薦引擎”"},"​")],-1)),n("p",null,[e[1]||(e[1]=t("編者注：本文是 2016 年 4 月 Nicole Whilte 在歐洲 ",-1)),a(o,{href:"http://graphconnect.com/"},{default:p(()=>[...e[0]||(e[0]=[t("GraphConnect",-1)])]),_:1}),e[2]||(e[2]=t(" 時所作。這兒我們快速回顧一下她所涉及的內容：",-1))]),e[27]||(e[27]=n("ul",null,[n("li",null,"圖資料庫推薦基礎"),n("li",null,"社會化推薦"),n("li",null,"相似性推薦"),n("li",null,"集羣推薦")],-1)),e[28]||(e[28]=n("p",null,"今天我們將要討論的內容是數據科學和圖推薦（graph recommendations）：",-1)),n("p",null,[e[5]||(e[5]=t("我在 ",-1)),a(o,{href:"http://neo4j.com/product/"},{default:p(()=>[...e[3]||(e[3]=[t("Neo4j",-1)])]),_:1}),e[6]||(e[6]=t(" 任職已經兩年了，但實際上我已經使用 Neo4j 和 ",-1)),a(o,{href:"http://neo4j.com/blog/why-database-query-language-matters/#cypher"},{default:p(()=>[...e[4]||(e[4]=[t("Cypher",-1)])]),_:1}),e[7]||(e[7]=t(" 工作三年了。當我首次發現這個特別的圖資料庫（graph database）的時候，我還是一個研究生，那時候我在奧斯丁的德克薩斯大學攻讀關於社交網絡的統計學碩士學位。",-1))]),n("p",null,[a(o,{href:"https://neo4j.com/use-cases/real-time-recommendation-engine/"},{default:p(()=>[...e[8]||(e[8]=[t("實時推薦引擎",-1)])]),_:1}),e[9]||(e[9]=t("是 Neo4j 中最廣泛的用途之一，也是使它如此強大並且容易使用的原因之一。為了探索這個東西，我將通過使用示例數據集來闡述如何將統計學方法併入這些引擎中。",-1))]),e[29]||(e[29]=s('<p>第一個很簡單 - 將 Cypher 用於社交推薦。接下來，我們將看一看相似性推薦，這涉及到可被計算的相似性度量，最後探索的是集羣推薦。</p><h3 id="圖資料庫推薦基礎" tabindex="-1">圖資料庫推薦基礎 <a class="header-anchor" href="#圖資料庫推薦基礎" aria-label="Permalink to “圖資料庫推薦基礎”">​</a></h3><p>下面的數據集包含所有達拉斯 Fort Worth 國際機場的餐飲場所，達拉斯 Fort Worth 國際機場是美國主要的機場樞紐之一：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816214938/recommendation-engine-data-science-nicole-white-graphconnect-768x432.png" alt=""></p><p>我們把節點標記成黃色並按照出入口和航站樓給它們的位置建模。同時我們也按照食物和飲料的主類別將地點分類，其中一些包括墨西哥食物、三明治、酒吧和烤肉。</p><p>讓我們做一個簡單的推薦。我們想要在機場的某一確定地點找到一種特定食物，大括號中的內容表示是的用户輸入，它將進入我們的假想應用程序中。</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816215426/food-drink-real-time-recommendation-engine-parameters-768x208.png" alt=""></p><p>這個英文句子表示成 Cypher 查詢：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816215537/cypher-query-dfw-food-drink-real-time-recommendations-768x364.png" alt=""></p><p>這將提取出該類別中用户所請求的所有地點、航站樓和出入口。然後我們可以計算出用户所在位置到出入口的準確距離，並以升序返回結果。再次説明，這個非常簡單的 Cypher 推薦僅僅依據的是用户在機場中的位置。</p><h3 id="社交推薦-social-recommendations" tabindex="-1">社交推薦（Social Recommendations） <a class="header-anchor" href="#社交推薦-social-recommendations" aria-label="Permalink to “社交推薦（Social Recommendations）”">​</a></h3><p>讓我們來看一下社交推薦。在我們的假想應用程序中，用户可以登錄並且可以用和 Facebook 類似的方式標記自己“喜好”的地點，也可以在某地簽到。</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816215655/social-media-recommendation-engine-data-model-768x550.png" alt=""></p><p>考慮位於我們所研究的第一個模型之上的數據模型，現在讓我們在下面的分類中找到用户的朋友喜好的航站樓裏面離出入口最近的餐飲場所：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816215751/social-recommendation-engine-parameters-768x258.png" alt=""></p><p>MATCH 子句和我們第一次 Cypher 查詢的 MATCH 子句相似，只是現在我們依據喜好和朋友來匹配：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816215846/social-recommendation-engine-cypher-query-768x468.png" alt=""></p><p>前三行是完全一樣的，但是現在要考慮的是那些登錄的用户，我們想要通過 :FRIENDS_WITH 這一關係來找到他們的朋友。僅需通過在 Cypher 中增加一些行內容，我們現在已經把社交層面考慮到了我們的推薦引擎中。</p><p>再次説明，我們僅僅顯示了用户明確請求的類別，並且這些類別中的地點與用户進入的地方是相同的航站樓。當然，我們希望按照登錄並做出請求的用户來濾過這些目錄，然後返回地點的名字、位置以及所在目錄。我們也要顯示出有多少朋友已經“喜好”那個地點以及那個地點到出入口的確切距離，然後在 RETURN 子句中同時返回所有這些內容。</p><h3 id="相似性推薦-similarity-recommendations" tabindex="-1">相似性推薦（Similarity Recommendations） <a class="header-anchor" href="#相似性推薦-similarity-recommendations" aria-label="Permalink to “相似性推薦（Similarity Recommendations）”">​</a></h3><p>現在，讓我們看一看相似性推薦引擎：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816215944/similarity-recommendation-engine-data-model-768x646.png" alt=""></p><p>和前面的數據模型相似，用户可以標記“喜好”的地點，但是這一次他們可以用 1 到 10 的整數給地點評分。這是通過前期在 Neo4j 中增加一些屬性到關係中建模實現的。</p><p>這將允許我們找到其他相似的用户，比如以上面的 Greta 和 Alice 為例，我們已經查詢了他們共同喜好的地點，並且對於每一個地點，我們可以看到他們所設定的權重。大概地，我們可以通過他們的評分來確定他們之間的相似性大小。</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220107/user-similarity-recommendation-engine-768x481.png" alt=""></p><p>現在我們有兩個向量：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220204/user-length-vectors-300x180.png" alt=""></p><p>現在讓我們按照歐幾里得距離（Euclidean distance）的定義來計算這兩個向量之間的距離：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220239/euclidean-distance-user-vectors.png" alt=""></p><p>我們把所有的數字帶入公式中計算，然後得到下面的相似度，這就是兩個用户之間的“距離”：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220323/user-vector-distance-similarity-metric-768x140.png" alt=""></p><p>你可以很容易地在 Cypher 中計算兩個特定用户的“距離”，特別是如果他們僅僅同時“喜好”一個很小的地點子集。再次説明，這兒我們依據兩個用户 Alice 和 Greta 來進行匹配，並嘗試去找到他們同時“喜好”的地點：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220517/similarity-recommendation-engine-Cypher-query-users-768x399.png" alt=""></p><p>他們都有對最後找到的地點的 :LIKES 關係，然後我們可以在 Cypher 中很容易的計算出他們之間的歐幾里得距離，計算方法為他們對各個地點評分差的平方求和再開平方根。</p><p>在兩個特定用户的例子中上面這個方法或許能夠工作。但是，在實時情況下，當你想要通過和實時資料庫中的其他用户比較，從而由一架飛機上的一個用户推斷相似用户時，這個方法就不一定能夠工作。不用説，至少它不能夠很好的工作。</p><p>為了找到解決這個問題的好方法，我們可以預先計算好距離並存入實際關係中：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220642/similarity-recommendation-engine-user-euclidean-distance-768x284.png" alt=""></p><p>當遇到一個很大的數據集時，我們需要成批處理這件事，在這個很小的示例數據集中，我們可以按照所有用户的迪卡爾乘積（Cartesian product）和他們共同“喜好”的地點來進行匹配。當我們使用 WHERE id（u1） &lt; id（u2） 作為 Cypher 詢問的一部分時，它只是來確定我們在左邊和右邊沒有找到相同的對的一個技巧。</p><p>通過用户之間的歐幾里得距離，我們創建了他們之間的一種關係，叫做 :DISTANCE，並且設置了一個叫做 euclidean 的歐幾里得屬性。理論上，我們可以也通過用户間的一些關係來存儲其他相似度從而獲取不同的相似度，因為在確定的環境下某些相似度可能比其他相似度更有用。</p><p>在 Neo4j 中，的確是對關係屬性建模的能力使得完成像這樣的事情無比簡單。然而，實際上，你不會希望存儲每一個可能存在的單一關係，因為你僅僅希望返回離他們“最近”的一些人。</p><p>因此你可以根據一些臨界值來存入前幾個，從而你不需要構建完整的連通圖。這允許你完成一些像下面這樣的實時的資料庫查詢，因為我們已經預先計算好了“距離”並存儲在了關係中，在 Cypher 中，我們能夠很快的攫取出數據。</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816220737/similarity-recommendation-engine-parameters-768x256.png" alt=""></p><p>在這個查詢中，我們依據地點和類別來進行匹配：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221031/similarity-real-time-recommendation-engine-cypher-query-768x384.png" alt=""></p><p>再次説明，前三行是相同的，除了登錄用户以外，我們找出了和他們有 :DISTANCE 關係的用户。這是我們前面查看的關係產生的作用 - 實際上，你只需要存儲處於前幾位的相似用户 :DISTANCE 關係，因此你不需要在 MATCH 子句中攫取大量用户。相反，我們只攫取和那些用户“喜好”的地方有 :DISTANCE 關係的用户。</p><p>這允許我們用少許幾行內容表達較為複雜的模型。我們也可以攫取 :LIKES 關係並把它放入到變量中，因為後面我們將使用這些權重來評分。</p><p>在這兒重要的是，我們可以依據“距離”大小將用户按照升序進行排序，因為這是一個距離測度。同時，我們想要找到用户間的最小距離因為距離越小表明他們的相似度最大。</p><p>通過其他按照歐幾里得距離大小排序好的用户，我們得到用户評分最高的三個地點並按照用户的平均評分高低來推薦這些地點。換句話説，我們先找出一個活躍用户，然後依據其他用户“喜好”的地點找出和他最相似的其他用户，接下來按照這些相似用户的平均評分把那些地點排序在結果的集合中。</p><p>本質上，我們通過把所有評分相加然後除以收集的用户數目來計算出平均分，然後按照平均評分的升序進行排序。其次，我們按照出入口距離排序。假想地，我猜測應該會有交接點，因此你可以按照出入口距離排序然後再返回名字、類別、出入口和航站樓。</p><h3 id="集羣推薦-cluster-recommendations" tabindex="-1">集羣推薦（Cluster Recommendations） <a class="header-anchor" href="#集羣推薦-cluster-recommendations" aria-label="Permalink to “集羣推薦（Cluster Recommendations）”">​</a></h3>',50)),n("p",null,[e[11]||(e[11]=t("我們最後要講的一個例子是集羣推薦，在 Cypher 中，這可以被想像成一個作為臨時解決方案的離線計算工作流。這可能完全基於在",-1)),a(o,{href:"https://neo4j.com/blog/neo4j-3-0-massive-scale-developer-productivity/"},{default:p(()=>[...e[10]||(e[10]=[t("歐洲 GraphConnect 上宣佈的新方法",-1)])]),_:1}),e[12]||(e[12]=t("，但是有時你必須進行一些 Cypher 2.3 版本所沒有的算法逼近。",-1))]),e[30]||(e[30]=s('<p>在這兒你可以使用一些統計軟件，把數據從 Neo4j 取出然後放入像 Apache Spark、R 或者 Python 這樣的軟件中。下面是一段把數據從 Neo4j 中取出的 R 代碼，運行該程序，如果正確，寫下程序返回結果的給 Neo4j，可以是一個屬性、節點、關係或者一個新的標籤。</p><p>通過持續把程序運行結果放入到圖表中，你可以在一個和我們剛剛看到的查詢相似的實時查詢中使用它：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221336/cluster-recommendation-r-code-algorithm-neo4j.png" alt=""></p><p>下面是用 R 來完成這件事的一些示例代碼，但是你可以使用任何你最喜歡的軟件來做這件事，比如 Python 或 Spark。你需要做的只是登錄並連接到圖表。</p><p>在下面的例子中，我基於用户的相似性把他們聚合起來。每個用户作為一個觀察點，然後得到他們對每一個目錄評分的平均值。</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221449/cluster-recommendation-engine-r-code-example-768x403.png" alt=""></p><p>假定用户對酒吧類評分的方式和一般的評分方式相似。然後我攫取出喜歡相同類別中的地點的用户名、類別名、“喜好”關係的平均權重，比如平均權重這些信息，從而我可以得到下面這樣一個表格：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221557/cluster-user-category-likes-768x295.png" alt=""></p><p>因為我們把每一個用户都作為一個觀察點，所以我們必須巧妙的處理每一個類別中的數據，這些數據的每一個特性都是用户對該類中餐廳評分的平均權重。接下來，我們將使用這些數據來確定用户的相似性，然後我將使用聚類（clustering）算法來確定在不同集羣中的用户。</p><p>在 R 中這很直接：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221716/clustering-algorith-recommendation-r-example-768x347.png" alt=""></p><p>在這個示例中我們使用 K-均值（k-means）聚類算法，這將使你很容易攫取集羣分配。總之，我通過運行聚類算法然後分別得到每一個用户的集羣分配。</p><p>Bob 和 David 在一個相同的集羣中 - 他們在集羣二中 - 現在我可以實時查看哪些用户被放在了相同的集羣中。</p><p>接下來我把集羣分配寫入 CSV 文件中，然後存入圖資料庫：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221805/load-csv-cypher-example-768x227.png" alt=""></p><p>我們只有用户和集羣分配，因此 CSV 文件只有兩列。 LOAD CSV 是 Cypher 中的內建語法，它允許你從一些其他文件路徑或者 URL 調用 CSV ，並給它一個別名。接下來，我們將匹配圖資料庫中存在的用户，從 CSV 文件中攫取用户列然後合併到集羣中。</p><p>我們在圖表中創建了一個新的標籤節點：Cluster ID， 這是由 K-平均聚類算法給出的。接下來我們創建用户和集羣間的關係，通過創建這個關係，當我們想要找到在相同集羣中的實際推薦用户時，就會很容易進行查詢。</p><p>我們現在有了一個新的集羣標籤，在相同集羣中的用户和那個集羣存在關係。新的數據模型看起來像下面這樣，它比我們前面探索的其他數據模型要更好：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816221913/clustering-recommendation-engine-data-model-768x401.png" alt=""></p><p>現在讓我們考慮下面的查詢：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816222009/clustering-recommendation-engine-parameters-768x259.png" alt=""></p><p>通過這個 Cypher 查詢，我們在更遠處找到了在同一個集羣中的相似用户。由於這個原因，我們刪除了“距離”關係：</p><p><img src="https://s3.amazonaws.com/dev.assets.neo4j.com/wp-content/uploads/20160816222045/cluster-recommendation-engine-cypher-query-example-768x385.png" alt=""></p><p>在這個查詢中，我們取出已經登錄的用户，根據用户-集羣關係找到他們所在的集羣，找到他們附近和他們在相同集羣中的用户。</p><p>我們把這些用户分配到變量 c1 中，然後我們得到其他被我取別名為 neighbor 變量的用户，這些用户和那個相同集羣存在着用户-集羣關係，最後我們得到這些附近用户“喜好”的地點。再次説明，我把“喜好”放入了變量 r 中，因為我們需要從關係中攫取權重來對結果進行排序。</p><p>在這個查詢中，我們所做的改變是，不使用相似性距離，而是攫取在相同集羣中的用户，然後對類別、航站樓以及我們所攫取的登錄用户進行聲明。我們收集所有的權重：來自附近用户“喜好”地點的“喜好”關係，得到的類別，確定的距離值，然後把它們按升序進行排序並返回結果。</p><p>在這些例子中，我們可以進行一個相當複雜的處理並且將其放到圖資料庫中，然後我們就可以使用實時算法結果-聚類算法和集羣分配的結果。</p><p>我們更喜歡的工作流程是更新這些集羣分配，更新頻率適合你自己就可以，比如每晚一次或每小時一次。當然，你可以根據直覺來決定多久更新一次這些集羣分配是可接受的。</p><hr>',29)),n("p",null,[e[14]||(e[14]=t("via: ",-1)),a(o,{href:"https://neo4j.com/blog/real-time-recommendation-engine-data-science/"},{default:p(()=>[...e[13]||(e[13]=[t("https://neo4j.com/blog/real-time-recommendation-engine-data-science/",-1)])]),_:1})]),n("p",null,[e[18]||(e[18]=t("作者：",-1)),a(o,{href:"https://neo4j.com/blog/contributor/nicole-white/"},{default:p(()=>[...e[15]||(e[15]=[t("Nicole White",-1)])]),_:1}),e[19]||(e[19]=t(" 譯者：",-1)),a(o,{href:"https://github.com/ucasFL"},{default:p(()=>[...e[16]||(e[16]=[t("ucasFL",-1)])]),_:1}),e[20]||(e[20]=t(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[23]||(e[23]=t("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[21]||(e[21]=[t("LCTT",-1)])]),_:1}),e[24]||(e[24]=t(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:p(()=>[...e[22]||(e[22]=[t("Linux中國",-1)])]),_:1}),e[25]||(e[25]=t(" 榮譽推出",-1))])])}const j=i(d,[["render",c]]);export{T as __pageData,j as default};
